/**
 * SillyTavernchat Module - Password migration for OAuth accounts
 *
 * Older STC-MOD versions created OAuth accounts with an EMPTY password. The official
 * login skips the password check for such accounts, so anybody knowing the handle could
 * log in. This one-time (per process) migration gives every such account a random,
 * never-disclosed password and flags it with `passwordAutoGenerated`, so the owner can
 * still set a real password later without knowing the old one.
 *
 * - Admin accounts are only secured when their OAuth provider is usable (otherwise the random
 *   password would lock the admin out); skipped ones are reported by the warning below.
 * - Non-admin accounts whose provider is not usable are secured too, and listed for the admin
 *   (they need a password reset in the user manager to log in again).
 * - Afterwards every remaining passwordless account (e.g. old local accounts) is logged.
 *
 * Idempotent: accounts that already have a password are skipped, so it is safe to run on
 * every startup. Existing sessions of migrated accounts are invalidated (account version
 * changes) – users simply log in again with their OAuth provider.
 */
import storage from 'node-persist';
import { getAllUserHandles, toKey } from '../../users.js';
import { getStcConfig } from '../config.js';
import { flushMetadata, getAllUserMeta, setUserMeta } from '../user-metadata.js';
import { OAUTH_PROVIDERS, applyRandomPassword, isMetaForRecord } from './account-security.js';

/** Yield to the event loop after this many accounts. */
const YIELD_EVERY = 50;

/** At most this many handles are listed in one log line. */
const MAX_LOGGED_HANDLES = 50;

const DEFAULT_USER_HANDLE = 'default-user';

/** @type {Promise<void>|null} */
let migrationPromise = null;

function yieldToEventLoop() {
    return new Promise(resolve => setImmediate(resolve));
}

/**
 * Whether the provider can currently be used to log in (enabled and has a client id).
 * @param {string} provider
 * @returns {boolean}
 */
function isProviderUsable(provider) {
    if (!getStcConfig(`oauth.${provider}.enabled`, false)) return false;
    const clientId = getStcConfig(`oauth.${provider}.clientId`, '');
    if (typeof clientId === 'number') return Number.isFinite(clientId);
    return typeof clientId === 'string' && clientId.trim() !== '';
}

/**
 * Join handles for a log line, truncated to MAX_LOGGED_HANDLES.
 * @param {string[]} handles
 * @returns {string}
 */
function formatHandles(handles) {
    const listed = handles.slice(0, MAX_LOGGED_HANDLES).join(', ');
    return handles.length > MAX_LOGGED_HANDLES ? `${listed}, …` : listed;
}

/**
 * Secure all passwordless OAuth accounts.
 * @returns {Promise<number>} Number of accounts that received a random password
 */
async function securePasswordlessOAuthAccounts() {
    /** @type {{handle: string, record: object, providerUsable: boolean}[]} */
    const candidates = [];
    /** @type {Map<string, boolean>} */
    const usableProviders = new Map();
    let processed = 0;

    // 1) Collect candidates
    for (const [handle, meta] of Object.entries(getAllUserMeta())) {
        if (!meta || typeof meta !== 'object' || !OAUTH_PROVIDERS.includes(meta.oauthProvider)) continue;
        if (handle === DEFAULT_USER_HANDLE) continue;

        processed++;
        if (processed % YIELD_EVERY === 0) {
            await yieldToEventLoop();
        }

        try {
            const record = await storage.getItem(toKey(handle));
            // Missing record, metadata left over from a deleted account whose handle was reused,
            // or an account that already has a password
            if (!record || record.password || !isMetaForRecord(meta, record)) continue;

            if (!usableProviders.has(meta.oauthProvider)) {
                usableProviders.set(meta.oauthProvider, isProviderUsable(meta.oauthProvider));
            }
            const providerUsable = usableProviders.get(meta.oauthProvider);

            // An admin without a usable provider would be locked out; the passwordless warning lists it
            if (record.admin && !providerUsable) continue;

            candidates.push({ handle, record, providerUsable });
        } catch (error) {
            console.error(`[STC-MOD] Password migration failed for ${handle}:`, error?.message || error);
        }
    }

    if (candidates.length === 0) return 0;

    // 2) Metadata first, flushed once: if we crash before a record is saved, the next run
    // redoes it (the record still has an empty password).
    for (const { handle } of candidates) {
        setUserMeta(handle, { passwordAutoGenerated: true, hasPassword: false });
    }
    flushMetadata();

    // 3) Records
    let secured = 0;
    /** Secured accounts whose provider is not usable: only an admin password reset lets them in. */
    const needsReset = [];
    for (const { handle, record, providerUsable } of candidates) {
        if (secured > 0 && secured % YIELD_EVERY === 0) {
            await yieldToEventLoop();
        }
        try {
            applyRandomPassword(record);
            await storage.setItem(toKey(handle), record);
            secured++;
            if (!providerUsable) needsReset.push(handle);
        } catch (error) {
            console.error(`[STC-MOD] Password migration failed for ${handle}:`, error?.message || error);
        }
    }

    if (needsReset.length > 0) {
        console.warn(`[STC-MOD] 以下第三方账号已设置随机密码，但其登录方式当前未启用，需管理员在用户管理中重置密码：${formatHandles(needsReset)}`);
    }

    return secured;
}

/**
 * Log every enabled account (except default-user) that can still be entered by handle alone.
 * @returns {Promise<void>}
 */
async function warnAboutPasswordlessAccounts() {
    const passwordless = [];
    const handles = await getAllUserHandles();

    for (let i = 0; i < handles.length; i++) {
        if (i > 0 && i % YIELD_EVERY === 0) {
            await yieldToEventLoop();
        }

        const handle = handles[i];
        if (handle === DEFAULT_USER_HANDLE) continue;
        try {
            const record = await storage.getItem(toKey(handle));
            if (record && record.enabled && !record.password) passwordless.push(handle);
        } catch (error) {
            console.error(`[STC-MOD] Password check failed for ${handle}:`, error?.message || error);
        }
    }

    if (passwordless.length > 0) {
        console.warn(`[STC-MOD] 以下账号没有密码，已禁止仅凭用户名登录，请在用户管理中为其设置密码：${formatHandles(passwordless)}`);
    }
}

/**
 * Run the password migration once per process. Later calls return the same promise.
 * The returned promise never rejects.
 * @returns {Promise<void>}
 */
export function runPasswordMigrationOnce() {
    if (!migrationPromise) {
        migrationPromise = securePasswordlessOAuthAccounts()
            .then((secured) => {
                console.log(`[STC-MOD] Password migration: ${secured} OAuth account(s) secured`);
            })
            .catch((error) => {
                console.error('[STC-MOD] Password migration failed:', error?.message || error);
            });

        // Diagnostic only: runs in the background so requests are not held while every
        // account record is read
        migrationPromise.then(() => warnAboutPasswordlessAccounts()).catch((error) => {
            console.error('[STC-MOD] Passwordless account check failed:', error?.message || error);
        });
    }
    return migrationPromise;
}
